package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.RequestObjectSigningAlgVO;

class RequestObjectSigningAlgValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of request object signing alg of oauth client")
  void test_request_object_signing_alg_value_holder_assign_plain_value() {
    Object holder = new Object();
    RequestObjectSigningAlgValueHolder<Object> value =
        new RequestObjectSigningAlgValueHolder<>(holder);
    Assertions.assertSame(holder, value.requestObjectSigningAlg("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getRequestObjectSigningAlgValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getRequestObjectSigningAlg().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.requestObjectSigningAlgNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getRequestObjectSigningAlgValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getRequestObjectSigningAlg().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of request object signing alg of oauth client")
  void test_request_object_signing_alg_value_holder_assign_value_object() {
    Object holder = new Object();
    RequestObjectSigningAlgValueHolder<Object> value =
        new RequestObjectSigningAlgValueHolder<>(holder);
    RequestObjectSigningAlgVO vo = RequestObjectSigningAlgVO.from("one");
    Assertions.assertFalse(value.getRequestObjectSigningAlgValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.requestObjectSigningAlg(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getRequestObjectSigningAlgValue().orElseThrow());
    Assertions.assertSame(holder, value.requestObjectSigningAlg(Optional.empty()));
    Assertions.assertFalse(value.getRequestObjectSigningAlgValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.requestObjectSigningAlg(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRequestObjectSigningAlgValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of request object signing alg of oauth client against the original")
  void test_request_object_signing_alg_value_holder_read() {
    Object holder = new Object();
    RequestObjectSigningAlgValueHolder<Object> value =
        new RequestObjectSigningAlgValueHolder<>(holder);
    RequestObjectSigningAlgVO vo = RequestObjectSigningAlgVO.from("one");
    RequestObjectSigningAlgVO other = RequestObjectSigningAlgVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getRequestObjectSigningAlgValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRequestObjectSigningAlg(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readRequestObjectSigningAlg(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.requestObjectSigningAlg(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRequestObjectSigningAlg(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRequestObjectSigningAlg(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of request object signing alg of oauth client")
  void test_request_object_signing_alg_value_holder_unset() {
    Object holder = new Object();
    RequestObjectSigningAlgValueHolder<Object> value =
        new RequestObjectSigningAlgValueHolder<>(holder);
    RequestObjectSigningAlgVO vo = RequestObjectSigningAlgVO.from("one");
    value.requestObjectSigningAlg(vo);
    Assertions.assertSame(holder,
        value.unsetRequestObjectSigningAlgIfMatches("requestObjectSigningAlg_other"));
    Assertions.assertTrue(value.getRequestObjectSigningAlgValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetRequestObjectSigningAlgIfMatches("requestObjectSigningAlg"));
    Assertions.assertFalse(value.getRequestObjectSigningAlgValue().isPresent(),
        "The field name must clear the value");
    value.requestObjectSigningAlg(vo);
    Assertions.assertSame(holder, value.unsetRequestObjectSigningAlg());
    Assertions.assertFalse(value.getRequestObjectSigningAlgValue().isPresent(),
        "Unset must clear the value");
  }
}
